package com.rudra.offlinepaymentrelay;
import android.Manifest;import android.app.Activity;import android.bluetooth.*;import android.bluetooth.le.*;import android.content.pm.PackageManager;import android.os.*;import android.widget.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class MainActivity extends Activity {
 static final UUID SERVICE=UUID.fromString("6d8f0001-8a5b-4b7d-9c2e-6e6f666c696e"),PAYMENT=UUID.fromString("6d8f0002-8a5b-4b7d-9c2e-6e6f666c696e");
 BluetoothGattServer server;BluetoothLeAdvertiser advertiser;TextView log;EditText api;final Executor io= new Executor();
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setPadding(24,28,24,20);l.setOrientation(1);setContentView(l);TextView title=new TextView(this);title.setText("Offline Payment Relay — demo");title.setTextSize(22);l.addView(title);api=new EditText(this);api.setText("http://10.0.2.2:8080/api/v1/payments/relay");api.setHint("Backend relay URL");l.addView(api);Button start=new Button(this);start.setText("Start relay");l.addView(start);Button stop=new Button(this);stop.setText("Stop relay");l.addView(stop);log=new TextView(this);l.addView(log);start.setOnClickListener(v->startRelay());stop.setOnClickListener(v->stopRelay());}
 void startRelay(){if(Build.VERSION.SDK_INT>=31&&(checkSelfPermission(Manifest.permission.BLUETOOTH_ADVERTISE)!=PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)!=PackageManager.PERMISSION_GRANTED)){requestPermissions(new String[]{Manifest.permission.BLUETOOTH_ADVERTISE,Manifest.permission.BLUETOOTH_CONNECT},7);return;}BluetoothManager m=getSystemService(BluetoothManager.class);BluetoothAdapter a=m.getAdapter();if(a==null||!a.isEnabled()){log.setText("Enable Bluetooth first.");return;}server=m.openGattServer(this,callback);BluetoothGattService s=new BluetoothGattService(SERVICE,BluetoothGattService.SERVICE_TYPE_PRIMARY);BluetoothGattCharacteristic c=new BluetoothGattCharacteristic(PAYMENT,BluetoothGattCharacteristic.PROPERTY_WRITE|BluetoothGattCharacteristic.PROPERTY_WRITE_NO_RESPONSE,BluetoothGattCharacteristic.PERMISSION_WRITE);s.addCharacteristic(c);server.addService(s);advertiser=a.getBluetoothLeAdvertiser();if(advertiser==null){log.setText("BLE advertising is not supported.");return;}AdvertiseSettings settings=new AdvertiseSettings.Builder().setAdvertiseMode(AdvertiseSettings.ADVERTISE_MODE_LOW_LATENCY).setConnectable(true).setTimeout(0).build();AdvertiseData data=new AdvertiseData.Builder().addServiceUuid(new android.os.ParcelUuid(SERVICE)).setIncludeDeviceName(false).build();advertiser.startAdvertising(settings,data,advertiseCallback);log.setText("Advertising as relay. Keep this screen open.");}
 final BluetoothGattServerCallback callback=new BluetoothGattServerCallback(){@Override public void onCharacteristicWriteRequest(BluetoothDevice d,int requestId,BluetoothGattCharacteristic c,boolean prepared,boolean responseNeeded,int offset,byte[] value){if(!PAYMENT.equals(c.getUuid())||offset!=0||value.length==0||value.length>480){if(responseNeeded)server.sendResponse(d,requestId,BluetoothGatt.GATT_INVALID_ATTRIBUTE_LENGTH,offset,null);return;}if(responseNeeded)server.sendResponse(d,requestId,BluetoothGatt.GATT_SUCCESS,offset,null);String json=new String(value,StandardCharsets.UTF_8);runOnUiThread(()->log.setText("Received intent over BLE. Forwarding to backend…"));io.execute(()->forward(json));}};
 final AdvertiseCallback advertiseCallback=new AdvertiseCallback(){@Override public void onStartSuccess(AdvertiseSettings s){runOnUiThread(()->log.setText("Relay advertising. Waiting for sender…"));}@Override public void onStartFailure(int e){runOnUiThread(()->log.setText("Advertising failed: "+e));}};
 void forward(String body){HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(api.getText().toString().trim()).openConnection();c.setRequestMethod("POST");c.setDoOutput(true);c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setRequestProperty("Content-Type","application/json");try(OutputStream o=c.getOutputStream()){o.write(body.getBytes(StandardCharsets.UTF_8));}int code=c.getResponseCode();if(code<200||code>=300)throw new IOException("Backend HTTP "+code);runOnUiThread(()->log.setText("Backend accepted relayed intent. Demo only; no money moved."));}catch(Exception e){runOnUiThread(()->log.setText("Forward failed: "+e.getMessage()+". Sender must retry; relay did not confirm acceptance."));}finally{if(c!=null)c.disconnect();}}
 void stopRelay(){if(advertiser!=null)advertiser.stopAdvertising(advertiseCallback);if(server!=null){server.close();server=null;}log.setText("Relay stopped.");}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==7&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)startRelay();else log.setText("Bluetooth advertise/connect permissions required.");}
 @Override protected void onDestroy(){stopRelay();super.onDestroy();}
 private static class Executor {private final java.util.concurrent.ExecutorService e=java.util.concurrent.Executors.newSingleThreadExecutor();void execute(Runnable r){e.execute(r);}}
}